import 'package:flutter/material.dart';import 'package:url_launcher/url_launcher.dart';
class ProfileScreen extends StatelessWidget{final String name,instagram;const ProfileScreen({super.key,required this.name,required this.instagram});Future<void> openInstagram()async{final u=instagram.replaceAll('@','').trim();final app=Uri.parse('instagram://user?username='+u),web=Uri.parse('https://instagram.com/'+u);if(await canLaunchUrl(app))await launchUrl(app,mode:LaunchMode.externalApplication);else await launchUrl(web,mode:LaunchMode.externalApplication);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[const CircleAvatar(radius:38,child:Icon(Icons.person,size:38)),const SizedBox(height:10),Text(name,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w700)),const SizedBox(height:12),FilledButton(onPressed:openInstagram,child:const Text('Instagram')),const SizedBox(height:24),const Expanded(child:GridPlaceholder())])));}
class MyProfile extends StatelessWidget{const MyProfile({super.key});@override Widget build(BuildContext context)=>const Padding(padding:EdgeInsets.all(20),child:Column(children:[CircleAvatar(radius:38,child:Icon(Icons.person,size:38)),SizedBox(height:10),Text('you',style:TextStyle(fontSize:22,fontWeight:FontWeight.w700)),SizedBox(height:24),Expanded(child:GridPlaceholder())]));}
class GridPlaceholder extends StatelessWidget{const GridPlaceholder({super.key});@override Widget build(BuildContext context)=>GridView.builder(gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,crossAxisSpacing:3,mainAxisSpacing:3),itemCount:12,itemBuilder:(_,__)=>Container(color:Colors.black12,child:const Icon(Icons.image_outlined)));}
